function statusFrom(c,max,a){if(!a)return'not-started';const p=Math.round(c/max*100);return p>=80?'achieved':p>=50?'progress':'not-achieved'}function statusLabel(s){return{achieved:'Objectif atteint',progress:'Objectif en cours d’acquisition','not-achieved':'Objectif non atteint','not-started':'Non commencé'}[s]||s}
function renderQualiopi(){const rows=$('#evaluationRows');if(!rows)return;rows.innerHTML=sectionDefs.map(d=>{if(d.manual){const s=state.manualStatus[d.id]||'not-started';return `<tr><td>${d.objective}</td><td>${d.subject}</td><td>${d.method}</td><td>Évaluation manuelle</td><td><span class="status ${s}">${statusLabel(s)}</span></td></tr>`}const st=state.sectionStats[d.id]||{c:0,a:0,max:d.max},s=statusFrom(st.c,d.max,st.a),pct=d.max?Math.round(st.c/d.max*100):0;return `<tr><td>${d.objective}</td><td>${d.subject}</td><td>${d.method}</td><td>${st.c}/${d.max} — ${pct}%</td><td><span class="status ${s}">${statusLabel(s)}</span></td></tr>`}).join('');refreshAdmin(false)}
function setupAdmin(){const saved=JSON.parse(localStorage.getItem('antoine-dark-past-admin')||'{}');$('#adminDate').value=new Date().toISOString().slice(0,10);['adminSession','adminDuration','adminRemaining','adminDate'].forEach(id=>{if(saved[id]!=null)$('#'+id).value=saved[id];$('#'+id).oninput=saveAdmin});$$('[data-manual-status]').forEach(sel=>{const id=sel.dataset.manualStatus;if(saved.manualStatus?.[id])sel.value=saved.manualStatus[id];state.manualStatus[id]=sel.value;sel.onchange=()=>{state.manualStatus[id]=sel.value;saveAdmin();renderQualiopi()}});$$('[data-manual-comment]').forEach(t=>{const id=t.dataset.manualComment;t.value=saved.manualComments?.[id]||'';state.manualComments[id]=t.value;t.oninput=()=>{state.manualComments[id]=t.value;saveAdmin();refreshAdmin(false)}});$('#refreshAdmin').onclick=()=>refreshAdmin(true);$('#copySpreadsheetRow').onclick=copySpreadsheetRow;$('#copyAdminSummary').onclick=copyAdminSummary;$$('.copy-btn').forEach(b=>b.onclick=()=>copyText($('#'+b.dataset.copy).value));renderQualiopi()}
function saveAdmin(){const x={};['adminSession','adminDuration','adminRemaining','adminDate'].forEach(id=>x[id]=$('#'+id).value);x.manualStatus=state.manualStatus;x.manualComments=state.manualComments;localStorage.setItem('antoine-dark-past-admin',JSON.stringify(x))}
function refreshAdmin(show){if(!$('#adminObjectives'))return;$('#adminObjectives').value='Distinguer et employer correctement le Past Simple et le Present Perfect ; automatiser les formes affirmatives, négatives et interrogatives ; sécuriser did/didn’t, was/were, have/has + participe passé ; reconnaître et employer les marqueurs temporels ; transférer les deux temps vers une production orale et écrite liée au parcours professionnel et au projet Australie.';$('#adminContent').value='Past Simple : temps fini, verbes réguliers/irréguliers, questions, négations et was/were. Present Perfect : have/has + participe passé, expérience, résultat actuel, période non terminée, since/for/already/yet/ever/never/just/recently/so far. Entraînement intensif et progressif : 16 rule checks, 80 exercices séparés sur les deux temps, 50 tâches contrastives, 45 tâches finales mixtes/VTest, vocabulaire du parcours professionnel, études, transition et Australie, puis productions orales et écrites.';$('#adminMethods').value='Progression pas à pas sans mélange prématuré ; explication explicite des règles ; exercices interactifs un par un ; correction immédiate avec explication ; bouton indice ; sujets variés ; répétition ciblée ; reconstruction de phrases type VTest ; audio manuel avec accents AU/UK/US ; modèles Strong B1 et B2/VTest ; production orale chronométrée ; production écrite guidée ; auto-évaluation.';const auto=sectionDefs.filter(d=>!d.manual).map(d=>{const st=state.sectionStats[d.id],s=statusFrom(st.c,d.max,st.a);return `${d.objective}: ${statusLabel(s)} (${st.c}/${d.max})`}).join(' | ');const man=sectionDefs.filter(d=>d.manual).map(d=>`${d.objective}: ${statusLabel(state.manualStatus[d.id]||'not-started')}${state.manualComments[d.id]?` — ${state.manualComments[d.id]}`:''}`).join(' | ');$('#adminEvaluation').value=auto+' | '+man;$('#adminResource').value='Page web interactive : '+(location.protocol==='file:'?'[ajouter le lien publié de la leçon]':location.href)+' — HTML/CSS/JS, exercices interactifs, feedback immédiat, indices, modèles, audio manuel, résultats et suivi Qualiopi.';if(show){$('#copyStatus').textContent='Admin text refreshed.';setTimeout(()=>$('#copyStatus').textContent='',1800)}}
async function copyText(text){try{await navigator.clipboard.writeText(text)}catch{const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove()}$('#copyStatus').textContent='Copied.';setTimeout(()=>$('#copyStatus').textContent='',1800)}
function copySpreadsheetRow(){refreshAdmin(false);copyText([$('#adminSession').value,$('#adminDuration').value,$('#adminRemaining').value,$('#adminDate').value,$('#adminObjectives').value,$('#adminContent').value,$('#adminMethods').value,$('#adminEvaluation').value,$('#adminResource').value].join('\t'))}function copyAdminSummary(){refreshAdmin(false);copyText(`Session: ${$('#adminSession').value}\nDurée: ${$('#adminDuration').value}\nHeures restantes: ${$('#adminRemaining').value}\nDate: ${$('#adminDate').value}\n\nObjectifs:\n${$('#adminObjectives').value}\n\nContenu:\n${$('#adminContent').value}\n\nMéthodes:\n${$('#adminMethods').value}\n\nÉvaluation:\n${$('#adminEvaluation').value}\n\nRessource:\n${$('#adminResource').value}`)}
function downloadResults(){refreshAdmin(false);const text=['ANTOINE · PAST TENSES CAREER SPRINT','====================================',`Interactive score: ${state.correct}/${state.attempted}`,`Progress: ${$('#progressText').textContent}`,'','Writing:', $('#writingAnswer').value||'(blank)','','Past Simple rule:', $('#exitPast').value||'(blank)','Present Perfect rule:', $('#exitPerfect').value||'(blank)','Personal target:', $('#exitWatch').value||'(blank)','','QUALIOPI:', $('#adminEvaluation').value].join('\n');const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Antoine_Past_Tenses_Career_Sprint_results.txt';a.click();URL.revokeObjectURL(a.href)}
function resetAll(){if(!confirm('Reset learner answers, scores and progress? Teacher/admin fields will be kept.'))return;state.completed.clear();state.correct=0;state.attempted=0;state.finalCorrect=0;state.finalAttempted=0;initStats();$$('.done-btn').forEach(b=>{b.classList.remove('completed');b.textContent='✓ Mark complete'});localStorage.removeItem('antoine-dark-past-writing');$('#writingAnswer').value='';$('#wordCount').textContent='0 words';['exitPast','exitPerfect','exitWatch'].forEach(id=>$('#'+id).value='');builderIndex=0;builderCorrect=0;initDecks();renderTransforms();renderBuilder();updateOverall();updateProgress();renderQualiopi()}
document.addEventListener('click',e=>{const sp=e.target.closest('[data-speak]');if(sp)speak(sp.dataset.speak);const done=e.target.closest('.done-btn');if(done)toggleDone(done);const model=e.target.closest('.model-toggle');if(model){const b=$('#'+model.dataset.model);b.classList.toggle('hidden');model.textContent=b.classList.contains('hidden')?'Show two models':'Hide models'}const tr=e.target.closest('.transform-check,.transform-hint,.transform-model');if(tr)handleTransform(tr)});
